using System.Collections;
using System.Reflection;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text.Json;
using BepInEx;using BepInEx.Configuration;using Studio;using UnityEngine;
var assembly=AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.GetFullPath(args[0]));
AssemblyLoadContext.Default.Resolving+=(ctx,n)=>{string p=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[0])),n.Name+".dll");return File.Exists(p)?ctx.LoadFromAssemblyPath(p):null;};
var pluginType=assembly.GetType("ManageableSkirts.ManageableSkirtsPlugin",true);
const BindingFlags All=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static;
void Call(object p,string method,params object[] values){try{pluginType.GetMethod(method,All).Invoke(p,values);}catch(TargetInvocationException e){throw e.InnerException;}}
void Set(object p,string field,bool value)=>((ConfigEntry<bool>)pluginType.GetField(field,All).GetValue(p)).Value=value;
(Color n,Color h,Color s) Colors(GuideSelect g)=>(g.Normal,g.Highlight,g.material.color);
var originalColor=(new Color(.2f,.3f,.4f,.25f),new Color(.4f,.5f,.6f,.9f),new Color(.12f,.23f,.34f,.67f));
OCIChar.BoneInfo Bone(string name,bool skirt,bool visible=true){var g=new GuideObject();g.visible=visible;g.transformTarget.name=name;g.transformTarget.position=new Vector3(0,0,skirt?int.Parse(name.Split('_')[3]):0);var s=new GuideSelect();s.Seed(originalColor.Item1,originalColor.Item2,originalColor.Item3);g.gameObject.Children.Add(s);s.gameObject.Children.Add(new Renderer{gameObject=s.gameObject});return new(){boneGroup=skirt?OIBoneInfo.BoneGroup.Skirt:OIBoneInfo.BoneGroup.Body,guideObject=g};}
(object p,OCIChar c) Make(bool depth=false){var p=(BaseUnityPlugin)Activator.CreateInstance(pluginType);foreach(var name in new[]{"enableColoring","enableDepthHiding","enableDirectionalCones","enableHideLastVisibleNode"})pluginType.GetField(name,All).SetValue(p,new ConfigEntry<bool>{Value=name=="enableColoring"});foreach(var name in new[]{"nodeOpacity","nodeSaturation","nodeBrightness"})pluginType.GetField(name,All).SetValue(p,new ConfigEntry<float>{Value=name=="nodeOpacity"?.75f:1f});pluginType.GetField("toggleHotkey",All).SetValue(p,new ConfigEntry<KeyboardShortcut>());pluginType.GetField("fNormal",All).SetValue(null,typeof(GuideBase).GetField("colorNormal",All));pluginType.GetField("fHighlight",All).SetValue(null,typeof(GuideBase).GetField("colorHighlighted",All));Set(p,"enableDepthHiding",depth);var c=new OCIChar();c.oiCharInfo.activeFK[6]=true;var spine=new Transform{name="cf_j_spine01"};c.charInfo.animBody.gameObject.Children.Add(spine);c.listBones.Add(Bone("body",false,false));for(int i=0;i<8;i++)c.listBones.Add(Bone("cf_j_sk_"+i+"_00",true));Singleton<Studio.Studio>.Instance=new();Singleton<Studio.Studio>.Instance.dicInfo[c.treeNodeObject]=c;Singleton<Studio.Studio>.Instance.treeNodeCtrl.selectNodes=new[]{c.treeNodeObject};Camera.main=new();return(p,c);}
void Check(bool b,string message){if(!b)throw new Exception(message);}
var results=new List<object>();int failureCount=0;
void Test(string name,Action action){try{action();results.Add(new{name,passed=true});}catch(Exception e){failureCount++;results.Add(new{name,passed=false,error=e.ToString()});}}
Test("hidden non-skirt guide preserved",()=>{var(p,c)=Make();Call(p,"ActivateCharacter",c);Call(p,"RestoreCharacter",c);Check(!c.listBones[0].guideObject.visible,"original hidden body made visible");});
Test("original skirt colors restored",()=>{var(p,c)=Make();var g=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>();var before=Colors(g);Call(p,"ActivateCharacter",c);Call(p,"RestoreCharacter",c);Check(Colors(g)==before,"original colors/material lost");});
Test("depth never removes ownership from native bone list",()=>{var(p,c)=Make(true);var before=c.listBones.ToArray();Call(p,"ActivateCharacter",c);Check(c.listBones.SequenceEqual(before),"native list membership changed");});
Test("foreign addition survives active update and restore",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);var add=Bone("foreign",false);c.listBones.Insert(0,add);Camera.main.transform.forward=new(0,0,-1);Call(p,"UpdateDepthIfActive");Call(p,"RestoreCharacter",c);Check(c.listBones.Contains(add),"foreign addition removed");});
Test("foreign removal stays removed",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);var removed=c.listBones[0];c.listBones.Remove(removed);Camera.main.transform.forward=new(0,0,-1);Call(p,"UpdateDepthIfActive");Call(p,"RestoreCharacter",c);Check(!c.listBones.Contains(removed),"foreign removal resurrected");});
Test("external color changes win on restore",()=>{var(p,c)=Make();var g=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>();Call(p,"ActivateCharacter",c);g.color=new(.9f,.2f,.6f,.8f);var external=Colors(g);Call(p,"RestoreCharacter",c);Check(Colors(g)==external,"external color overwritten");});
Test("deleted character guides do not escape restore",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);c.charInfo.Destroyed=true;foreach(var b in c.listBones)b.guideObject.Destroyed=true;Call(p,"RestoreAll");});
Test("clothing guide replacement does not reuse destroyed snapshot",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);foreach(var b in c.listBones)b.guideObject.Destroyed=true;var replacement=Bone("cf_j_sk_1_00",true);c.listBones=new(){replacement};Camera.main.transform.forward=new(0,0,-1);Call(p,"UpdateDepthIfActive");Call(p,"RestoreCharacter",c);Check(c.listBones.Count==1&&ReferenceEquals(c.listBones[0],replacement),"clothing list overwritten");});
Test("repeated toggle restores hidden original",()=>{var(p,c)=Make(true);for(int i=0;i<4;i++){Call(p,"ToggleSelectedCharacter");Call(p,"ToggleSelectedCharacter");}Check(!c.listBones[0].guideObject.visible,"repeated toggle unhid body");});
Test("far-side chains stay hidden while near-side visible",()=>{var(p,c)=Make(true);var before=c.listBones.ToArray();Call(p,"ActivateCharacter",c);Check(before.Skip(6).All(b=>!b.guideObject.visible)&&before.Skip(1).Take(5).All(b=>b.guideObject.visible),"depth ranking changed");Camera.main.transform.forward=new(0,0,-1);Call(p,"UpdateDepthIfActive");Check(before.Skip(1).Take(3).All(b=>!b.guideObject.visible)&&before.Skip(4).All(b=>b.guideObject.visible),"camera reversal ranking changed");});
Test("same native list instance and order retained",()=>{var(p,c)=Make(true);var list=c.listBones;var before=list.ToArray();Call(p,"ActivateCharacter",c);Camera.main.transform.forward=new(0,0,-1);Call(p,"UpdateDepthIfActive");Call(p,"RestoreCharacter",c);Check(ReferenceEquals(list,c.listBones)&&list.SequenceEqual(before),"native ownership/order changed");});
Test("external hidden skirt remains hidden",()=>{var(p,c)=Make();Call(p,"ActivateCharacter",c);var g=c.listBones[1].guideObject;g.visible=false;Call(p,"RestoreCharacter",c);Check(!g.visible,"external hide undone");});
Test("external far-side show is not re-hidden or restored",()=>{var(p,c)=Make(true);var g=c.listBones[8].guideObject;Call(p,"ActivateCharacter",c);g.visible=true;Call(p,"UpdateDepthIfActive");Call(p,"RestoreCharacter",c);Check(g.visible,"external show overwritten");});
Test("disabling depth releases only owned hiding",()=>{var(p,c)=Make(true);var before=c.listBones.ToArray();Call(p,"ActivateCharacter",c);Set(p,"enableDepthHiding",false);Call(p,"Update");Check(!before[0].guideObject.visible&&before.Skip(1).All(b=>b.guideObject.visible),"disabled depth left hidden output");});
Test("disabling coloring restores captured colors",()=>{var(p,c)=Make();var g=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>();var before=Colors(g);Call(p,"ActivateCharacter",c);Set(p,"enableColoring",false);Call(p,"Update");Check(Colors(g)==before,"disabled color left output");});
Test("new live skirt guide recognized without changing list",()=>{var(p,c)=Make();Call(p,"ActivateCharacter",c);var add=Bone("cf_j_sk_3_01",true);c.listBones.Add(add);var select=add.guideObject.gameObject.GetComponentInChildren<GuideSelect>();var before=Colors(select);Call(p,"UpdateDepthIfActive");Check(Colors(select)!=before&&c.listBones.Contains(add),"new live skirt was ignored");Call(p,"RestoreCharacter",c);Check(Colors(select)==before,"new guide color not restored");});
Test("replacement custom material is preserved",()=>{var(p,c)=Make();var g=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>();Call(p,"ActivateCharacter",c);var replacement=new Material{color=new(.71f,.83f,.97f,.61f)};g.material=replacement;var before=replacement.color;Call(p,"RestoreCharacter",c);Check(ReferenceEquals(g.material,replacement)&&replacement.color==before,"external material modified");});
Test("missing camera does not fail activation or restore",()=>{var(p,c)=Make(true);Camera.main=null;Call(p,"ActivateCharacter",c);Call(p,"RestoreCharacter",c);Check(!c.listBones[0].guideObject.visible,"hidden original changed");});
Test("actual Update hotkey toggles and restores",()=>{var(p,c)=Make(true);KeyboardShortcut.Pressed=true;Call(p,"Update");KeyboardShortcut.Pressed=true;Call(p,"Update");Check(!c.listBones[0].guideObject.visible&&c.listBones.Count==9,"hotkey restore changed original");});
Test("destroyed root retires session and permits new toggle",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);c.charInfo.animBody.gameObject.Children[0].Destroyed=true;Call(p,"UpdateDepthIfActive");var tracked=(IDictionary)pluginType.GetField("tracked",All).GetValue(p);Check(!tracked.Contains(c),"dead session not retired");});
Test("one failing restore remains observable and other guides restore",()=>{var(p,c)=Make(true);var before=c.listBones.ToArray();Call(p,"ActivateCharacter",c);before[8].guideObject.FailVisibilityWrite=true;bool threw=false;try{Call(p,"RestoreCharacter",c);}catch(Exception){threw=true;}Check(threw,"restore error hidden");Check(before[6].guideObject.visible&&before[7].guideObject.visible,"other guides not restored");before[8].guideObject.FailVisibilityWrite=false;Call(p,"RestoreCharacter",c);Check(before[8].guideObject.visible,"failed guide state could not be retried");});
Test("idle Update does not alter unrelated character",()=>{var(p,c)=Make();var before=c.listBones.ToArray();var colors=Colors(before[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>());for(int i=0;i<20;i++)Call(p,"Update");Check(c.listBones.SequenceEqual(before)&&!before[0].guideObject.visible&&Colors(before[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>())==colors,"idle update changed state");});
Test("missing Studio instance permits safe session cleanup",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);Singleton<Studio.Studio>.Instance=null;c.charInfo.Destroyed=true;Call(p,"UpdateDepthIfActive");var tracked=(IDictionary)pluginType.GetField("tracked",All).GetValue(p);Check(tracked.Count==0,"missing studio prevented retirement");});
Test("missing character native component skips activation",()=>{var(p,c)=Make(true);c.charInfo=null;Call(p,"ActivateCharacter",c);var tracked=(IDictionary)pluginType.GetField("tracked",All).GetValue(p);Check(tracked.Count==0,"missing native character activated");});
Test("replaced character controller retires old state",()=>{var(p,c)=Make(true);Call(p,"ActivateCharacter",c);c.charInfo=new ChaControl();Call(p,"UpdateDepthIfActive");var tracked=(IDictionary)pluginType.GetField("tracked",All).GetValue(p);Check(tracked.Count==0,"changed controller retained old session");});
Test("foreign highlighted style and emission survive restore",()=>{var(p,c)=Make();var g=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>();Call(p,"ActivateCharacter",c);var foreign=new Color(.13f,.41f,.73f,.99f);typeof(GuideBase).GetField("colorHighlighted",All).SetValue(g,foreign);g.material.SetColor("_EmissionColor",foreign);Call(p,"RestoreCharacter",c);Check(g.Highlight==foreign&&g.material.GetColor("_EmissionColor")==foreign,"external highlighted/emission values lost");});

IList Entries(object p,OCIChar c)=> (IList)((IDictionary)pluginType.GetField("tracked",All).GetValue(p))[c].GetType().GetField("allEntries").GetValue(((IDictionary)pluginType.GetField("tracked",All).GetValue(p))[c]);
object EField(object e,string n)=>e.GetType().GetField(n).GetValue(e);
void AddChainEnds(OCIChar c){for(int chain=0;chain<8;chain++){var b=Bone("cf_j_sk_"+chain+"_01",true);b.guideObject.transformTarget.position=new Vector3(0,1,chain);c.listBones.Add(b);}}
Test("V2 cone geometry creation retained",()=>{var(p,c)=Make();AddChainEnds(c);Set(p,"enableDirectionalCones",true);Call(p,"ActivateCharacter",c);var entries=Entries(p,c).Cast<object>().Where(e=>(bool)EField(e,"isSkirt")).ToArray();Check(entries.All(e=>(GameObject)EField(e,"coneObject")),"cones missing");var cone=(GameObject)EField(entries[0],"coneObject");var mesh=cone.GetComponent<MeshFilter>().sharedMesh;Check(mesh.vertices.Length==99&&mesh.subMeshCount==2&&mesh.Triangles[0].Length==48&&mesh.Triangles[1].Length==51,"original half cone geometry changed");Call(p,"RestoreCharacter",c);Check(entries.All(e=>EField(e,"coneObject")==null),"cones not cleaned");});
Test("native renderer original disabled restored",()=>{var(p,c)=Make();AddChainEnds(c);Set(p,"enableDirectionalCones",true);var renderer=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>().gameObject.GetComponent<Renderer>();renderer.enabled=false;Call(p,"ActivateCharacter",c);Call(p,"RestoreCharacter",c);Check(!renderer.enabled,"renderer originally disabled was enabled");});
Test("cone mode toggle cleans and recreates owned objects",()=>{var(p,c)=Make();AddChainEnds(c);Set(p,"enableDirectionalCones",true);Call(p,"ActivateCharacter",c);var entries=Entries(p,c).Cast<object>().Where(e=>(bool)EField(e,"isSkirt")).ToArray();var previous=(GameObject)EField(entries[0],"coneObject");Set(p,"enableDirectionalCones",false);pluginType.GetField("directionalGuidesEnabledLastFrame",All).SetValue(p,true);Call(p,"LateUpdate");Check(previous.Destroyed&&EField(entries[0],"coneObject")==null,"cone off not cleaned");Set(p,"enableDirectionalCones",true);Call(p,"LateUpdate");Check((GameObject)EField(entries[0],"coneObject"),"cone on not recreated");Call(p,"RestoreCharacter",c);});
Test("hide last weighted node keeps complete native list",()=>{var(p,c)=Make();AddChainEnds(c);Set(p,"enableHideLastVisibleNode",true);var original=c.listBones.ToArray();Call(p,"ActivateCharacter",c);Check(c.listBones.SequenceEqual(original),"last node removed from native list");Check(original.Skip(9).All(b=>!b.guideObject.visible),"last nodes not hidden");Call(p,"RestoreCharacter",c);Check(original.Skip(9).All(b=>b.guideObject.visible),"last hiding not restored");});
Test("V2 opacity change preserves original color on restore",()=>{var(p,c)=Make();var select=c.listBones[1].guideObject.gameObject.GetComponentInChildren<GuideSelect>();var before=Colors(select);Call(p,"ActivateCharacter",c);((ConfigEntry<float>)pluginType.GetField("nodeOpacity",All).GetValue(p)).Value=.4f;Call(p,"UpdateDepthIfActive");Check(select.Normal.a==.4f,"V2 opacity not honored");Call(p,"RestoreCharacter",c);Check(Colors(select)==before,"opacity change lost original");});
Test("native active flag restored without touching body",()=>{var(p,c)=Make();c.listBones[1].active=false;c.listBones[0].active=false;Call(p,"ActivateCharacter",c);Call(p,"RestoreCharacter",c);Check(!c.listBones[1].active&&!c.listBones[0].active,"active flags not restored");});
Test("removed cone target refreshes without native list repair",()=>{var(p,c)=Make();AddChainEnds(c);Set(p,"enableDirectionalCones",true);Call(p,"ActivateCharacter",c);var removed=c.listBones[9];c.listBones.Remove(removed);Call(p,"UpdateDepthIfActive");Call(p,"UpdateConeGuides");Call(p,"RestoreCharacter",c);Check(!c.listBones.Contains(removed),"removed target resurrected");});
var output=new{adapterSha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(args[0]))).ToLowerInvariant(),checks=results.Count,results,scope="Actual original/candidate managed methods against synthetic Unity/Game/BepInEx assemblies. No Unity native execution, installed config, scenes or cards touched."};
File.WriteAllText(args[1],JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(output));

if(failureCount>0)Environment.ExitCode=1;
